#!/bin/sh
# Every recipe, compiled and run against a fixture this script makes.
#
#   sh scripts/check.sh [WORKDIR]
#
# What it needs: ffrwd 0.18.0 or newer and ffmpeg on the PATH, the four
# modules built (cargo build --target wasm32-wasip2 --release), this
# package's dependencies installed (ffrwd install) and the models already
# in ffrwd's cache. Nothing is published.
#
# WORKDIR defaults to a directory under the system temporary one and is
# removed on the way out. Everything the fixture needs is generated by
# lavfi, so no media is in the repository and none is left behind.
#
# The compile-only half runs first and on its own terms: `ffrwd validate`
# over describe.sql and describe-video.sql type-checks the whole query,
# the weave's rows argument and its space table included, without a model
# being loaded, because nothing in those two runs at compile time. The
# find recipes embed their prompt while they compile, so they cannot be
# checked without the text towers, and they need a file with records in
# it - which is why the second half describes the fixture first.
set -eu

for needed in ffrwd ffmpeg ffprobe; do
  command -v "$needed" >/dev/null 2>&1 || { echo "$needed is not on the PATH" >&2; exit 2; }
done

HERE=$(cd "$(dirname "$0")/.." && pwd)
WORK=${1:-${TMPDIR:-/tmp}/ffrwd-describe-check.$$}
mkdir -p "$WORK"
trap 'rm -rf "$WORK"' EXIT
# Absolute and in the platform's own spelling: a recipe's `src` reaches
# ffprobe unchanged, and a path only this shell understands would probe
# as a different file or as none.
case $(uname -s 2>/dev/null || echo unknown) in
  MINGW*|MSYS*|CYGWIN*) WORK=$(cd "$WORK" && pwd -W) ;;
esac

fail=0
say() { printf '\n== %s ==\n' "$1"; }
ok() { printf '  ok   %s\n' "$1"; }
bad() { printf '  FAIL %s\n' "$1"; fail=1; }

# Eight seconds, a hard cut every two: enough shots for the detector to
# find, small enough that the towers run in seconds.
say "the fixture"
ffmpeg -hide_banner -nostdin -y -loglevel error \
  -f lavfi -i "testsrc2=size=320x240:rate=24:duration=2" \
  -f lavfi -i "smptebars=size=320x240:rate=24:duration=2" \
  -f lavfi -i "testsrc=size=320x240:rate=24:duration=2" \
  -f lavfi -i "color=c=blue:size=320x240:rate=24:duration=2" \
  -filter_complex '[0:v][1:v][2:v][3:v]concat=n=4:v=1[v]' -map '[v]' \
  -c:v libx264 -pix_fmt yuv420p -g 24 "$WORK/silent.mp4"
ffmpeg -hide_banner -nostdin -y -loglevel error \
  -i "$WORK/silent.mp4" -f lavfi -i "anoisesrc=color=pink:sample_rate=48000:amplitude=0.3" \
  -shortest -c:v copy -c:a aac -ac 2 "$WORK/sound.mp4"
echo "  $WORK/silent.mp4, $WORK/sound.mp4"

say "compile, without a model"
if ffrwd validate -f "$HERE/recipes/describe-video.sql" \
     -v "src=$WORK/silent.mp4" -v "dest=$WORK/out.mp4" >/dev/null; then
  ok "describe-video.sql compiles"
else
  bad "describe-video.sql compiles"
fi
if ffrwd validate -f "$HERE/recipes/describe.sql" \
     -v "src=$WORK/sound.mp4" -v "dest=$WORK/out.mkv" >/dev/null; then
  ok "describe.sql compiles"
else
  bad "describe.sql compiles"
fi
# The audio the one reads and the other does not is the whole reason
# there are two, so the refusal is worth asserting rather than assuming.
if ffrwd validate -f "$HERE/recipes/describe.sql" \
     -v "src=$WORK/silent.mp4" -v "dest=$WORK/out.mp4" 2>&1 | grep -q STREAM_NOT_FOUND; then
  ok "describe.sql refuses a silent source by name"
else
  bad "describe.sql refuses a silent source by name"
fi

say "describe, for real"
for ext in mp4 mkv; do
  if ffrwd run -f "$HERE/recipes/describe-video.sql" \
       -v "src=$WORK/silent.mp4" -v "dest=$WORK/described.$ext" -y -q >/dev/null 2>&1; then
    ok "describe-video.sql writes .$ext"
  else
    bad "describe-video.sql writes .$ext"
    continue
  fi
  # The weave hosts on a stream copy, so the pictures are the source's
  # own. A difference here is the filter touching what it must not.
  before=$(ffmpeg -v error -nostdin -i "$WORK/silent.mp4" -map 0:v:0 -f framemd5 - | grep -v '^#' | md5sum)
  after=$(ffmpeg -v error -nostdin -i "$WORK/described.$ext" -map 0:v:0 -f framemd5 - | grep -v '^#' | md5sum)
  if [ "$before" = "$after" ]; then
    ok "the .$ext pictures are the source's own"
  else
    bad "the .$ext pictures are the source's own"
  fi
done

say "find, over what describe wrote"
if [ -f "$WORK/described.mp4" ]; then
  # A threshold of zero keeps every record whose vector points anywhere
  # near the prompt, which is what a check wants: this is about the read
  # path and the trims, not about the ranking.
  if ffrwd run -f "$HERE/recipes/find-video.sql" -v "src=$WORK/described.mp4" \
       -v "prompt=colour bars" -v "threshold=0.0" -v "dest=$WORK/found.mp4" -y -q >/dev/null 2>&1; then
    ok "find-video.sql cuts the spans back out"
  else
    bad "find-video.sql cuts the spans back out"
  fi
fi
if ffrwd run -f "$HERE/recipes/describe.sql" -v "src=$WORK/sound.mp4" \
     -v "dest=$WORK/described_sound.mp4" -y -q >/dev/null 2>&1; then
  ok "describe.sql writes a file with sound"
else
  bad "describe.sql writes a file with sound"
fi
# Three spaces declared and three woven. The clip vectors arrive as an
# annotation column and the other two out of a rows function, which are
# two different ways into the same filter, so a run that got one and
# not the others would still write a file that looked fine.
if [ -f "$WORK/described_sound.mp4" ]; then
  cat > "$WORK/spaces.sql" <<SQL
COPY (
  SELECT s.modality
  FROM input('$WORK/described_sound.mp4') f, ffrwd.index.spaces(f.video[1]) s
) TO '$WORK/spaces.json' WITH (format 'json')
SQL
  ffrwd run -f "$WORK/spaces.sql" -y -q >/dev/null 2>&1 || true
  found=$(grep -c '"modality"' "$WORK/spaces.json" 2>/dev/null || true)
  if [ "${found:-0}" -eq 3 ]; then
    ok "the file declares three spaces"
  else
    bad "the file declares three spaces (found ${found:-0})"
  fi
fi
if [ -f "$WORK/described_sound.mp4" ] &&
   ffrwd run -f "$HERE/recipes/find.sql" -v "src=$WORK/described_sound.mp4" \
     -v "prompt=colour bars" -v "threshold=0.0" -v "dest=$WORK/found_sound.mp4" -y -q >/dev/null 2>&1; then
  ok "find.sql cuts video and audio back out"
else
  bad "find.sql cuts video and audio back out"
fi

say "done"
exit $fail
